import {
  BaseSheet,
  FillRangeOperation,
  InsertColOperation,
  InsertRowOperation,
  UpdateMergeCellOperation,
  Operation,
  RemoveColOperation,
  RemoveRowOperation,
  Sheet,
  UpdateCellOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, beforeEach, test, afterEach } from 'vitest';

describe.concurrent('left side to update-cell right side to:', () => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: UpdateCellOperation = {
    type: 'update-cell',
    at: [6, 6],
    newV: null,
    oldV: {
      value: 2,
    },
    id: '1',
  };
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', op12);
    console.log('op21,', op21);

    doc1 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op1) as BaseSheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', JSON.stringify(doc1));
    console.log('doc2,', JSON.stringify(doc2));
    expect(doc1).toStrictEqual(doc2);
  });

  test('update-cell', () => {
    op2 = {
      type: 'update-cell',
      at: op1.at,
      newV: {
        value: 4,
      },
      oldV: {
        value: 2,
      },
      id: '1',
    } as UpdateCellOperation;
  });

  describe('insert-row', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at[0] - 3,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at[0] + 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at[0],
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
  });

  describe('remove-row', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at[0] - 3,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at[0] + 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at[0],
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
  });

  describe('insert-col', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at[0] - 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at[0] + 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at[0],
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
  });

  describe('remove-col', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at[0] - 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at[0] + 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at[0],
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
  });

  describe.concurrent('fill-range', () => {
    test('without intersection', () => {
      op2 = {
        type: 'fill-range',
        range: [3, 3, 5, 5],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('intersection', () => {
      op2 = {
        type: 'fill-range',
        range: [5, 5, 8, 8],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
  });

  describe.concurrent('merge-cell', () => {
    test('without intersection', () => {
      op2 = {
        type: 'update-merge',
        newV: [3, 3, 5, 5],
        uuid: '1',
        id: '1',
      } as UpdateMergeCellOperation;
    });
    test('intersection', () => {
      op2 = {
        type: 'update-merge',
        newV: [5, 5, 8, 8],
        uuid: '1',
        id: '1',
      } as UpdateMergeCellOperation;
    });
  });
  describe.concurrent('unmerge-cell', () => {
    test('without intersection', () => {
      op2 = {
        type: 'update-merge',
        newV: [3, 3, 5, 5],
        uuid: '1',
        id: '1',
      } as UpdateMergeCellOperation;
    });
    test('intersection', () => {
      op2 = {
        type: 'update-merge',
        newV: [5, 5, 8, 8],
        uuid: '1',
        id: '1',
      } as UpdateMergeCellOperation;
    });
  });
});
